package org.autojs.autojs.core.pref

import org.junit.AfterClass
import org.junit.Assert.fail
import org.junit.BeforeClass
import org.junit.Test
import java.io.File

/**
 * The declarations of every domain in [SettingsRegistry.DOMAINS] against the P0 baseline (docs/settings/ROADMAP.md P2,
 * R2): the value type and the default of each `SettingKey` agree with a source that P0.4 recorded for the key
 * (the data of docs/settings/defaults.md as generated by P1.0), a computed default
 * reads exactly the resource its source names, and Enum keys have their default among the candidates, which are all
 * registered value constants. The baseline is the frozen copy `tools/settings/baseline/defaults-p0.json`, since
 * inventory.py now also reads the declarations themselves. Kind, category, deployment and effect are checked by [SettingsRegistryGuardTest].
 *
 * zh-CN: 以 P0 基线核对 [SettingsRegistry.DOMAINS] 中各领域的声明 (ROADMAP P2, R2): 每个 `SettingKey` 的值类型与默认值与 P0.4
 * 为该键记录的某个来源一致 (defaults.md 的数据), 计算型默认值读取的正是其来源所写的资源, Enum 键的默认值在候选项中且候选项都已
 * 登记为设置值常量. kind / 分类 / 部署项 / 生效方式由 [SettingsRegistryGuardTest] 核对.
 */
class SettingsDomainsTest {

    @Test
    fun computedDefaultsReadTheResourceTheyName() {
        val problems = mutableListOf<String>()
        var checked = 0
        declaredKeys().forEach { key ->
            val default = key.default as? SettingDefault.Computed ?: return@forEach
            if (!default.source.startsWith("R.")) return@forEach
            SettingsTestResources.reads.clear()
            key.defaultOrNull()
            checked++
            val reads = SettingsTestResources.reads.toList()
            if (reads != listOf(default.source)) problems.add("${key.name}: source ${default.source}, read $reads")
        }
        println("P2 resource defaults checked: $checked")
        assertNone("computed defaults that read another resource than their source names", problems)
    }

    @Test
    fun typesAndDefaultsMatchTheBaseline() {
        val problems = mutableListOf<String>()
        var checked = 0
        declaredKeys().filterIsInstance<SettingKey<*>>().forEach { key ->
            val baselineName = baselineNameOf(key)
            val qualified = "${key.store.name}:$baselineName"
            if (!key.store.isDefault && qualified in NAMED_STORE_DEFAULTS) {
                val expected = NAMED_STORE_DEFAULTS[qualified]
                if (key.defaultText != expected) problems.add("$qualified: default ${key.defaultText}, expected $expected (the old reader of the named store)")
                checked++
                return@forEach
            }
            if (baselineName in KEYS_AFTER_P0) {
                val expected = KEYS_AFTER_P0[baselineName]
                if (key.defaultText != expected) problems.add("$baselineName: default ${key.defaultText}, expected $expected (added after P0)")
                checked++
                return@forEach
            }
            val sources = baselineDefaults[baselineName] ?: baselineDefaults.entries.firstOrNull { (name, _) ->
                // A family template is named by its prefix; P0.4 recorded some families as globs ("key_$_x_$_*").
                "*" in name && name.substringBefore("*") == baselineName
            }?.value
            if (sources == null) {
                problems.add("$baselineName: no default source in the baseline")
                return@forEach
            }
            sources.mapNotNull { it["type"] as String? }.filter { !isCompatible(key.type, it) }.forEach {
                problems.add("$baselineName: declared ${key.type.tag}, the baseline has a $it source")
            }
            if (sources.none { matches(key, it) }) {
                problems.add("$baselineName: default ${key.default} matches none of ${sources.map { it["expr"] to it["value"] }}")
            }
            checked++
        }
        println("P2 settings checked against the baseline defaults: $checked")
        assertNone("declarations that disagree with the P0.4 default sources", problems)
    }

    @Test
    fun enumDefaultsAndCandidatesAreRegistered() {
        val problems = mutableListOf<String>()
        val constants = SettingsRegistry.describe().filter { it.kind == SettingKind.VALUE_CONSTANT }.map { it.name }.toSet()
        val candidates = mutableSetOf<String>()
        SettingsRegistry.keys.filterIsInstance<SettingKey.Enum<*>>().forEach { key ->
            if (!key.isDefaultCandidate()) problems.add("${key.name}: default ${key.defaultOrNull()} is not a candidate")
            key.enumType.candidateKeys.forEach { candidate ->
                candidates.add(candidate)
                if (candidate !in constants) problems.add("${key.name}: candidate $candidate is not a registered value constant")
            }
        }
        val exempt = VALUE_CONSTANTS_WITHOUT_ENUM.map { SettingsTestResources.value("string", it) }.toSet()
        (constants - candidates - exempt).forEach { problems.add("value constant $it is no candidate of a declared Enum key") }
        assertNone("Enum keys and value constants", problems)
    }

    // ------------------------------------------------------------------------------------------------- helpers

    /** The declared keys and the templates of the declared key families (P3). */
    private fun declaredKeys(): List<PrefKey<*>> = SettingsRegistry.keys + SettingsRegistry.families.map { it.template }

    private fun baselineNameOf(key: PrefKey<*>): String = if (key.keyRes != 0) SettingsTestResources.nameOf("string", key.keyRes) else key.name

    private fun isCompatible(type: SettingType<*>, baselineType: String): Boolean = when (type.tag) {
        "bool" -> baselineType == "Boolean"
        "int" -> baselineType == "Int"
        "long" -> baselineType == "Long"
        "float" -> baselineType == "Float"
        "string" -> baselineType == "String" || baselineType == "String (Enum)"
        "stringSet" -> baselineType == "StringSet"
        "json" -> baselineType.startsWith("Json")
        else -> false
    }

    /** True when [source] (one baseline default source) is where the declared default of [key] comes from. */
    private fun matches(key: SettingKey<*>, source: Map<String, Any?>): Boolean = when (val default = key.default) {
        // P0.4 annotated some values ("[] (键不存在时)").
        is SettingDefault.Constant -> source["value"] == key.defaultText || (source["value"] as String?)?.startsWith("${key.defaultText} (") == true
        SettingDefault.None -> source["value"] == "null"
        is SettingDefault.Computed -> {
            val resource = Regex("""^R\.(bool|integer|string)\.(\w+)$""").find(default.source)
            when (resource) {
                // A run-time expression, or the fallback a reader returns for a missing key, which P0.4 recorded in
                // the value column ("[] (... DEFAULT_DECLARATION_GROUPS)").
                null -> source["expr"] == default.source || (source["value"] as String?)?.contains(default.source) == true
                // Hand-written sources of P0.4 name the resource in the expression only.
                else -> source["form"] == "R.${resource.groupValues[1]}" &&
                        (source["ref"] == resource.groupValues[2] || (source["expr"] as String?)?.contains(default.source) == true) &&
                        source["value"] == key.defaultOrNull().toString()
            }
        }
    }

    private fun assertNone(message: String, items: List<String>) {
        if (items.isNotEmpty()) fail("$message (${items.size}):\n  " + items.sorted().joinToString("\n  "))
    }

    companion object {

        /**
         * Registered value constants (resource names) that no declared Enum key lists as a candidate: the font ids of
         * the bundled catalog (the font key is a Str, fonts are downloaded) and the values of the legacy pinch strategy,
         * a state (P4.2).
         */
        private val VALUE_CONSTANTS_WITHOUT_ENUM = listOf(
            "key_ace_editor_font_cascadia_code", "key_ace_editor_font_fira_code", "key_ace_editor_font_hack",
            "key_ace_editor_font_ibm_plex_mono", "key_ace_editor_font_intel_one_mono", "key_ace_editor_font_iosevka",
            "key_ace_editor_font_iosevka_slab", "key_ace_editor_font_jetbrains_mono", "key_ace_editor_font_source_code_pro",
            "key_ace_editor_font_system_monospace",
            "key_editor_pinch_to_zoom_change_text_size", "key_editor_pinch_to_zoom_disable", "key_editor_pinch_to_zoom_scale_view",
        )

        /**
         * Settings the P0 baseline has no default source for: resource or literal name -> default text (null for none).
         * zh-CN: P0 基线没有默认值来源的设置: 资源名或字面量名称 -> 默认值文本 (无默认值为 null).
         */
        private val KEYS_AFTER_P0: Map<String, String?> = mapOf(
            // fragment_developer_options.xml app:defaultValue="true" (memory roadmap P1.2, appendix C Q16).
            "key_leakcanary_enabled" to "true",
            // fragment_developer_options.xml app:defaultValue="true", MemoryDiagnostics getBoolean(..., true) (memory
            // roadmap P2.3, appendix C Q21).
            "key_memory_unreclaimed_warning" to "true",
            // fragment_developer_options.xml app:defaultValue="false" (memory roadmap P5.1, appendix C Q8).
            "key_memory_script_heap_dump" to "false",
            // Literal names the P0 inventory missed (appendix C Q15, P3.6); the defaults are those of the old readers:
            // Pref.getBoolean(KEY_DERIVED_COLORS, false), Pref.getBoolean(KEY_HISTORY_MERGE_SIMILAR, false),
            // Pref.getString(ROOT_CONFIGURATION_KEY, "{}"), booleanOrFalse / stringOrNull of the compiler opt-in stores
            // and getString(selectionPreferenceKey(...), null) of the debug model selection.
            "THEME_COLOR_DERIVED_ACCENT_AND_DARK" to "false",
            "COLOR_HISTORY_MERGE_SIMILAR" to "false",
            "three_stove_agent_script_root_configuration" to "{}",
            "dex_compiler_experimental_enabled" to "false",
            "dex_compiler_experimental_component" to null,
            "r8_compiler_explicit_enabled" to "false",
            "r8_compiler_explicit_component" to null,
            "key_\$_codegen_model_current_debug_" to null,
        )

        /**
         * Keys of named stores whose defaults P0.4 did not record (its table covers the default preferences and some
         * literal keys only): "store:name" -> the default of the old reader (null for none), P3.
         * zh-CN: P0.4 未记录默认值的命名存储键 (其默认值表只覆盖默认偏好与部分字面量键): "存储:名称" -> 旧读取方的默认值 (无为 null), P3.
         */
        private val NAMED_STORE_DEFAULTS: Map<String, String?> = mapOf(
            // P3.4: GitHubTokenStore getString(KEY_TOKEN, null); PluginAuthorizationStore getBoolean(key, false); the
            // trust confirmations getBoolean(signer, false); BunHostCapabilityGrants keeps a default per capability.
            "github_auth:github_token" to null,
            "plugin_center_authorization:key_\$_plugin_auth_\$_" to "false",
            "mcp_server_trust_confirmation:*" to "false",
            "three_stove_agent_trust_confirmation:*" to "false",
            "bun_host_capability_grants:*" to null,
            // P3.1: the plugin center stores. The primary sort P0.4 recorded as its reader's parameter "defaultSortOrdinal",
            // whose default is Sort.defaultPrimarySort().ordinal; ascending and secondary sorts fall back per column
            // (Sort.defaultAscending, defaultSecondarySort()), the mechanism / source secondaries to the defaults of
            // their columns; hidden titles and sources, launcher icon choices: getString(key, null); suspension:
            // getBoolean(key, false).
            "plugin_center_visibility_state:key_\$_plugin_center_hidden_title_" to null,
            "plugin_center_visibility_state:key_\$_plugin_center_hidden_source_" to null,
            "plugin_launcher_icons:*" to null,
            "plugin_center_enable_state:key_\$_suspended_plugin_\$_" to "false",
            // P3.2: SymbolsConfigStore getString(KEY_ACTIVE_PROFILE, PROFILE_DEFAULT_ID) and getString(KEY_PROFILES_JSON,
            // null); AceEditorFontUiPreferences getBoolean(typeLockedKey(field), field.typeLockedByDefault) and
            // getString(KEY_SELECTED_VARIANT_PREFIX + groupId, null).
            "editor_symbols_config:active_profile" to "__default__",
            "editor_symbols_config:profiles_json" to null,
            "ace_editor_font_ui_preferences:key_\$_ace_editor_font_name_sort_type_locked" to "AceEditorFontSortField.NAME.typeLockedByDefault",
            "ace_editor_font_ui_preferences:key_\$_ace_editor_font_size_sort_type_locked" to "AceEditorFontSortField.SIZE.typeLockedByDefault",
            "ace_editor_font_ui_preferences:key_\$_ace_editor_font_selected_variant_" to null,
            // P3.3: BuildConfigStore getString(KEY_ACTIVE_PROFILE, PROFILE_DEFAULT_ID) / getString(KEY_PROFILES_JSON, null);
            // WizardProfileStore getString(keyCustomProfiles, null) / getBoolean(keyShowDone, showDoneByDefault = true),
            // P0.4 recorded the two wizards under one combined name; the launcher icon option getBoolean(key, true);
            // JvmSourceProviderSelection getString(storageKey(language), null); UpdateIgnoreStore getStringSet(key, emptySet()).
            "build_apk_config_profiles:active_profile" to "__default__",
            "build_apk_config_profiles:profiles_json" to null,
            "permission_wizard:key_\$_permission_wizard_custom_profiles" to null,
            "permission_wizard:key_\$_permission_wizard_show_done" to "true",
            "plugin_install_wizard:key_\$_plugin_install_wizard_custom_profiles" to null,
            "plugin_install_wizard:key_\$_plugin_install_wizard_show_done" to "true",
            "plugin_install_wizard:show_launcher_icons_for_new_plugins" to "true",
            "jvm_source_provider_selection:exact_component" to null,
            "jvm_source_provider_selection:exact_component_kotlin" to null,
            "key_\$_ignored_updates:key_\$_ignored_plugin_\$_" to "[]",
        ) + listOf("", "_official", "_third_party").flatMap { list ->
            val base = "plugin_center_sort_state:key_\$_plugin_center_sort_state$list"
            listOf(
                base to "Sort.defaultPrimarySort().ordinal",
                "${base}_ascending_" to null,
                "${base}_secondary_" to null,
                "${base}_mechanism_secondary" to "Sort.MECHANISM.defaultSecondarySort().ordinal",
                "${base}_source_secondary" to "Sort.SOURCE.defaultSecondarySort().ordinal",
            )
        }

        private lateinit var resources: AutoCloseable
        private lateinit var baselineDefaults: Map<String, List<Map<String, Any?>>>

        @BeforeClass
        @JvmStatic
        fun load() {
            resources = SettingsTestResources.install()
            val file = File(SettingsTestResources.root, "tools/settings/baseline/defaults-p0.json")
            @Suppress("UNCHECKED_CAST")
            val inventory = SettingsJson.parse(file.readText()) as Map<String, Any?>
            @Suppress("UNCHECKED_CAST")
            baselineDefaults = (inventory["defaults"] as Map<String, Any?>).mapValues { (_, list) -> (list as List<Any?>).map { it as Map<String, Any?> } }
        }

        @AfterClass
        @JvmStatic
        fun restore() {
            resources.close()
        }    }
}
